mapper.select:
select t.hm_id,t.hm_id hmId,t.license,t.prod_url,t.prod_url prodUrl,t.author,t.link,t.status_cd,t.status_cd
statusCd,t.default_protocol,t.default_protocol defaultProtocol,t.hm_name,t.hm_name
hmName,t.protocol_impl,t.protocol_impl protocolImpl,t.version,t.hm_type,t.hm_type hmType
from hardware_manufacturer t
where 1 =1

    and t.hm_id= #{hmId}


    and t.license= #{license}


    and t.prod_url= #{prodUrl}


    and t.author= #{author}


    and t.link= #{link}


    and t.status_cd= #{statusCd}


    and t.default_protocol= #{defaultProtocol}


    and t.hm_name= #{hmName}


    and t.protocol_impl= #{protocolImpl}


    and t.version= #{version}


    and t.hm_type= #{hmType}

order by t.create_time desc

    limit #{page}, #{row}

